architecture.h4_f:
msg = CBOR{v:1, тэкст, reply_to, sent_at}
ct = AES-GCM-256-Шыфраваць(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, тэкст, reply_to?, thread_id?, згадкі?, sent_at}
ct = AES-GCM-256-Шыфраваць(ключ_пакоя, nonce, pt, aad=hex(ідэнтыфікатар_пакоя))
провад = CBOR{
  v: 1,
  зашыфраваны тэкст: hex(ct), // зменная даўжыня
  nonce: hex (12 B),
  sender_pseudo: hex (16 B),
  sent_at: unix_ms
}

cryptoWire.h5_f:
знешні = CBOR{
  крыніца_вузел: hex32,
  мэтавы_карыстальнік: int64,
  inner_ciphertext: байты,
  inner_nonce: байты,
  sent_at: unix_ms
}
sig = Ed25519-Sign(source_priv, знешні)
POST /federation/deliver { канверт: знешні, сіг: hex64 }

auth.h1_f:
POST /api/authentication/register
  { імя карыстальніка, пароль, x25519_public_key, display_name, phone?, email?, avatar_emoji }

Адказ 201 створаны:
  { access_token, refresh_token, user_id, username, ...}

auth.h3_f:
access_token карысная нагрузка:
  { sub: user_id, jti: device_id, typ: "доступ", exp: зараз + 15 хвілін }
карысная нагрузка refresh_token:
  { sub: user_id, jti: device_id, typ: "абнавіць", exp: зараз + 30d }

HS256 падпісана 64-байтавым сакрэтам вузла з .env

auth.h4_f:
register_begin(): выклік = rand(32)
                    параметры = {rp.id, user.id, pubKeyCredParams, выклік}
                    варыянты вяртання

register_finish(атэстацыя):
  праверыць атэстацыю на TPM / Secure Enclave root CA
  захоўваць {ідэнтыфікатар_уліковых дадзеных, адкрыты_ключ, лічыльнік: 0}

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR карысная нагрузка = { nonce, user_id, сервер: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → зарэгістравана новая прылада; JWT вярнуліся.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 шаснаццатковы
зашыфраваны тэкст = AES-GCM-Шыфраванне(ключ_пакоя, nonce, CBOR_карысная нагрузка, aad=ідэнтыфікатар_пакоя)

Разгорнуты фрэйм: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {імя файла, памер, chunk_size_hint}
            ← {upload_id, chunk_size}
кавалак PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct байтаў>
            ← 204
завяршыць POST /api/files/resumable/{upload_id}/фіналізаваць {plain_blake3}
            ← 201 {file_id, url}
TTL на незавершаным: 24 гадз

files.h4_f:
дэні_спіс = {
  "прыкладанне/x-dosexec",
  "прыкладанне/x-sharedlib",
  "прыкладанне/x-mach-binary",
}
if magic.from_buffer(buf[:1024]) у deny_list: вяртае 415

presence.h1_f:
кліент: пры першым націску клавішы → адправіць {type:"t", state:"start"}
         больш не адпраўляе на працягу 3 с, калі стан не зменіцца
         10 с пасля апошняга націску клавішы → адправіць {type:"t", state:"stop"}
прыёмнік: аўтаматычны прыпынак праз 10 с пасля апошняга "старту", калі "стоп" не паступіў

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS трансляцыя {type:"c", kind:"invite", call_id}
WS трансляцыя {type:"c", kind:"offer", sdp}
WS трансляцыя {type:"c", kind:"answer", sdp}
WS трансляцыя {type:"c", kind:"candidate",ice} × N
POST /api/calls/{call_id}/канец

federation.h2_f:
канверт = {
  зыходны_вузел: hex32,
  мэтавы_карыстальнік: int64,
  inner_ciphertext: байты,
  inner_nonce: байты,
  sent_at: unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(канверт))
POST /federation/deliver { канверт, знак }

gossip.h3_f:
рэклама = {пабключ, канчатковая кропка, аб'яўленае_на}
sig = Ed25519-Sign(pubkey_priv, CBOR(рэклама))
карысная нагрузка плётак: [..., {рэклама, знак}, ...]

атрымальнік: праверыць sig на ad.pubkey → захоўваць, калі нармальна
дадаткова: PoW з 2^18 вядучых нулёў на {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template with {
  выпадковы = наш выпадковы,
  server_name = наша імя хоста (або ECH),
  session_id = наш ідэнтыфікатар сесіі,
}
JA4 = t13d_xxxx_xxxx_xxxx (супадае з бягучай стабільнай версіяй Chrome)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {імя: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: дамен(t) = база32( SHA256(пачатак ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(request) {decrypt(request.content.userInfo)}
Android FCM: onMessageReceived(remoteMessage) { расшыфраваць(remoteMessage.data)}
Вэб SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
інструмент = знак_інструмента
input = зыходнае дрэва, ключы/release.key
маніфест = {
  версія: "0.1.0",
  убудаваны: unix_ms,
  файлы: [{шлях, sha256, памер}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(маніфест))
выхад = INTEGRITY.sig.json = {маніфест, signed_by: pub_hex, sig: sig_hex}

bots.h1_f:
стварыць: POST /api/bots {імя карыстальніка, адлюстраванае_імя, код}
          → {bot_id, маркер, pubkey}
запуск: у працэсе (супраграма ўнутры вузла)
      OR знешні (доўгі апытанне /api/bots/{id}/updates, token-auth'd)
паведамленне: {тэкст, подпіс: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
на /пачаць {
  выдаць "Вітаем, {ctx.first_name}"
}
на / дадаць <элемент> {
  state.list = (state.list або []) + [ctx.args.item]
  emit "Дададзена: {ctx.args.item}"
}

security.h4_f:
canary.txt (штодня):
  {дата, знак: Ed25519-Sign(release_priv, дата)}
кліент правярае → адсутнічае або несапраўдны ⇒ падазрэнне на скампраметацыю

надзвычайная сітуацыя:
  адміністратар POST /api/admin/revoke-all {прычына}
  трансляцыі вузла {тып:"n", падзея:"кампраміс", прычына}
  кліенты сцерці ключы, прымусова перазагрузіцца

debugging.h2_f:
гістаграмы хуткасці (за маршрут + метад):
